INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1012, '数学', '三年级', '选择', 2, '{"stem": "根据四则运算的顺序，计算下面算式时需要先计算“25+6”的是（ ）。A. 186−25+6  B. 186+(25+6)  C. 25+(6+4)  D. 25+6×4", "options": null}', 'B', 'A 同级从左往右先算 186−25；B 带括号先算括号内 25+6；C 先算括号内 6+4；D 先算乘法 6×4。选 B。', 'paper', '["practice", "VG-G3-1-4", "ykl3sx", "1.6"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1011, '数学', '三年级', '选择', 3, '{"stem": "下面四个小伙伴，谁算得对？计算正确的有（ ）。A. 453−128+72=453−200=253  B. 136−7×4=136−28=108  C. 63÷7×5=9×5=45  D. 56−36÷4=20÷4=5", "options": null}', 'B（2个正确：B和C）', 'A 同级应从左往右：453−128=325，325+72=397，错；B 先乘后减 136−28=108，对；C 同级乘除从左往右 63÷7=9，9×5=45，对；D 应先算除法 36÷4=9，56−9=47，错。所以正确的是 B 和 C，共 2 个，选 B。', 'paper', '["practice", "VG-G3-1-3", "ykl3sx", "1.6"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '选择', 2, '{"stem": "一根绳子长180厘米，第一次剪去35厘米，第二次剪去45厘米。剩下的绳长与原来的绳长相差多少厘米？以下列式中正确的是（ ）。A. 35+45  B. 180−35−45  C. 180−35+45  D. 180−(35+45)", "options": null}', 'A', '相差的长度=剪去的总长度=35+45=80（厘米），选 A。（D 求的是剩下的长度）', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.6"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "学校进行嘉年华活动，小红和亮亮参加夹弹珠项目。小红第一次夹了36颗，第二次夹了28颗；亮亮两次夹的总颗数比小红少15颗。亮亮一共夹了多少颗弹珠？", "options": null}', '49颗', '小红两次共夹：36+28=64（颗）；亮亮：64−15=49（颗）。综合算式：36+28−15=49。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.6"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "乐乐用50根火柴棒摆同样的图形（每个图形用4根火柴棒），摆了这样的9个后，还剩下多少根火柴棒？", "options": null}', '14根', '9个图形共用：9×4=36（根）；剩下：50−36=14（根）。综合算式：50−9×4=14。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.6"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
