INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 3, '{"stem": "乘出租车（不计等候费）：A市出租车起步费14元（包含3千米），超出3千米后按每千米2元计费。（1）小海一家乘出租车行了10千米，要付多少元？", "options": null}', '28元', '超出部分：10−3=7（千米）；超出费用：7×2=14（元）；共付：14+14=28（元）。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.6"]', NULL, 0);

