INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "商品价格：书包98元/个，笔袋28元/个，尺8元/把，薯片8元/包，书70元/本。（1）欢欢买了一个笔袋和2把尺，一共用去多少元？", "options": null}', '44元', '28+2×8=28+16=44（元）。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.6"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 3, '{"stem": "商品价格：书包98元/个，笔袋28元/个，尺8元/把，薯片8元/包，书70元/本。（2）如果你有100元，你能买哪些东西呢？还剩多少元？结合计算说一说。（答案不唯一）", "options": null}', '答案不唯一，如：买1个书包，100−98=2（元），还剩2元；或买3个笔袋，100−3×28=16（元），还剩16元；或买1个笔袋和1本书，100−28−70=2（元）等。', '所买物品总价不超过100元即可，用100元减去总价就是剩下的钱。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.6"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 3, '{"stem": "商品价格：书包98元/个，笔袋28元/个，尺8元/把，薯片8元/包，书70元/本。（3）结合所给信息，说说算式“70−2×8”能解决什么问题？生活中还有哪些问题也能用这个算式解决，举例说一说。（答案不唯一）", "options": null}', '如：一本书70页，欢欢每天看8页，看了2天，还剩多少页没看？70−2×8=54（页）；或：欢欢带70元买2把尺（8元/把），还剩多少元？70−2×8=54（元）。', '“70−2×8”表示从70里先减去2个8，可表示“总量−2份每份8的量=剩余量”的一类问题。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.6"]', NULL, 0);
